/**
 * Prepend a banner to a body with a blank line separator.
 * @param {string} banner
 * @param {string} body
 * @returns {string}
 */
export function prependBanner(banner, body) {
	if (!body || !body.trim()) return banner
	return `${banner}\n\n${body.trimStart()}`
}
